def get_git_chapter_levels() -> list[tuple[str, list[tuple[str, str]]]]:
    """قالب فصل برای full_curriculum؛ ساختار دقیقاً مشابه سایر فصل‌های مخزن است."""
    grouped: dict[str, list[dict[str, Any]]] = {}
    for item in TOPICS:
        grouped.setdefault(item["group"], []).append(item)
    out: list[tuple[str, list[tuple[str, str]]]] = []
    for group, items in grouped.items():
        lessons: list[tuple[str, str]] = []
        for item in items:
            for code, fa, en in LEVELS:
                title = f"[{code}] {item['fa']} — {fa}"
                title_en = f"[{code}] {item['fa']} — {en}"
                lessons.append((title, title_en))
        out.append((group, lessons))
    return out


def is_git_title(title: str) -> bool:
    t = (title or "").casefold()
    return (
        "git workflow" in t
        or any(re.sub(r"\s+", " ", item["fa"]).strip().casefold() in re.sub(r"\s+", " ", t).strip() for item in TOPICS)
    )


def chapter_summary() -> dict[str, int]:
    return {
        "sections": len({item['group'] for item in TOPICS}),
        "topics": len(TOPICS),
        "levels_per_topic": len(LEVELS),
        "lessons": len(TOPICS) * len(LEVELS),
    }
